<script setup lang="ts">
import {nextTick,ref} from 'vue';import Icon from '../../shared/Icon.vue';
const props=defineProps<{reason:string;error?:string|null;saveDisabled:boolean;startDisabled:boolean;closeBlocked?:boolean;retrying?:boolean;acknowledged?:boolean;hasFiles?:boolean;newImport?:boolean;discardDisabled?:boolean;promptBusy?:boolean;saveLabel?:string}>();
const emit=defineEmits<{opened:[];closed:[];save:[];discard:[];submit:[];background:[kind:'local'|'library'];blockedClose:[]}>();const dialog=ref<HTMLDialogElement>(),confirm=ref<HTMLDialogElement>(),closePrompt=ref(false);
function showModal(){if(dialog.value&&!dialog.value.open){dialog.value.showModal();emit('opened');}return dialog.value?.open??false;}
function close(){if(props.closeBlocked){emit('blockedClose');return false;}if(props.newImport&&props.hasFiles&&props.saveDisabled){emit('blockedClose');return false;}if(props.newImport&&props.hasFiles){closePrompt.value=true;void nextTick(()=>confirm.value?.showModal());return false;}if(props.newImport){emit('discard');return false;}dialog.value?.close();return true;}
function stay(){confirm.value?.close();closePrompt.value=false;}
function savePrompt(){stay();emit('save');}
function forceClose(){confirm.value?.close();closePrompt.value=false;dialog.value?.close();}
function backdrop(event:MouseEvent){if(event.target===dialog.value)close();}
defineExpose({showModal,close,forceClose,get open(){return dialog.value?.open??false;}});
</script>
<template><dialog ref="dialog" class="mask import-dialog-mask" role="presentation" @cancel.prevent="close" @close="emit('closed')" @click="backdrop"><div class="import-dialog modal xl aci-import-modal" role="dialog" aria-modal="true" aria-label="导入会议" aria-labelledby="import-dialog-title"><div class="modal-h"><div class="aci-import-heading"><div id="import-dialog-title" class="m-t" role="heading" aria-level="2">导入会议</div><div class="aci-import-desc">采集会议内容</div></div><button type="button" class="m-x" aria-label="关闭导入会议" @click="close"><Icon name="x" :size="18"/></button></div><div class="modal-b"><slot/>
 <slot name="materials"> <section class="aci-import-section"><div class="ac-material-heading"><h3>会议背景材料及相关文档</h3><div class="flex wrap"><button type="button" class="btn" @click="emit('background','local')">上传本地文件</button><button type="button" class="btn" @click="emit('background','library')">从知识库选择</button></div></div><div class="small muted mb12">补充材料有助于更精准理解会议内容和生成纪要；未添加时，将基于会议录音或转写内容处理。</div><div data-aci-files="material"></div><div class="upload-zone ac-material-drop" role="button" tabindex="0" @click="emit('background','local')" @keydown.enter.prevent="emit('background','local')" @keydown.space.prevent="emit('background','local')" @dragover.prevent @drop.prevent="emit('background','local')">可拖入背景材料，也可从知识库选择；无材料可直接开始处理。</div><input hidden multiple type="file" aria-label="选择背景材料" accept=".pdf,.pptx,.docx"/></section></slot><div class="aci-import-error ac-error" role="alert">{{error}}</div></div>
 <div class="modal-f"><div class="aci-import-footer" :key="reason+saveDisabled+startDisabled+retrying+acknowledged"><div class="small" :class="startDisabled&&!acknowledged?'ac-error':'muted'" role="status">{{reason}}</div><div class="flex"><button type="button" class="btn" :disabled="saveDisabled" :title="saveDisabled?'请先导入会议主文件':undefined" @click="emit('save')">{{saveLabel??'保存并返回列表'}}</button><button type="button" class="btn primary" :disabled="startDisabled" @click="emit('submit')">{{retrying?'重试原导入请求':acknowledged?'查看处理进度':'开始处理'}}</button></div></div></div></div></dialog><dialog v-if="closePrompt" ref="confirm" class="mask import-dialog-mask" role="presentation" @cancel.prevent="stay" @click="event=>{if(event.target===confirm)stay();}"><div class="modal" role="dialog" aria-modal="true" aria-label="保存本次导入？"><div class="modal-h"><div class="m-t">保存本次导入？</div><button type="button" class="m-x" aria-label="关闭保存提示" @click="stay"><Icon name="x" :size="18"/></button></div><div class="modal-b">文件已暂存。可保存到会议列表稍后继续，或放弃本次新增会议。<div v-if="error" class="ac-error small mt12" role="alert">{{error}}</div></div><div class="modal-f"><button type="button" class="btn" :disabled="promptBusy" @click="stay">继续导入</button><button type="button" class="btn" :disabled="discardDisabled||promptBusy" @click="emit('discard')">放弃本次导入</button><button type="button" class="btn primary" :disabled="saveDisabled" @click="savePrompt">保存并返回列表</button></div></div></dialog></template>
<style scoped>
.import-dialog.modal.xl.aci-import-modal{padding:0;border:0;margin:0;color:var(--text);background:white;overflow:visible;box-sizing:border-box;max-width:calc(100vw - 40px);max-height:90vh;width:1000px;border-radius:10px;box-shadow:var(--shadow-lg)}
.import-dialog-mask{inset:0;width:auto;height:auto;max-width:none;max-height:none;padding:0;margin:0;border:0;color:var(--text);overflow:visible}.import-dialog-mask:not([open]){display:none}.import-dialog-mask::backdrop{background:transparent}
</style>
